from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png'))
for y in range(26,52):
 s=[]
 for x in range(104,156):
  r,g,b=im[y,x]
  if r>170 and r>g*1.35 and r>b*1.35: s.append('#')
  elif b>r*1.2: s.append('B')
  elif r>220 and g>180 and b>180: s.append('o')
  elif r>210 and g>210 and b>210: s.append('W')
  else: s.append('.')
 print(f'{y:02}', ''.join(s))
